content.content:
1	---
2	import AdminLayout from "../../layouts/AdminLayout.astro";
3	---
4	
5	<AdminLayout title="Review Uploads" activePage="reception-reviews">
6	  <div class="rev-page-shell">
7	    <div class="rev-page-header">
8	      <div>
9	        <div class="page-title">Google Review Uploads</div>
10	        <div class="page-subtitle">
11	          Upload a screenshot of each Google review you receive. It counts toward this month's Google Reviews KPI.
12	        </div>
13	      </div>
14	      <div class="rev-page-actions">
15	        <label class="rev-action-control">
16	          <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
17	            <rect x="3" y="4" width="18" height="18" rx="2"></rect>
18	            <line x1="16" y1="2" x2="16" y2="6"></line>
19	            <line x1="8" y1="2" x2="8" y2="6"></line>
20	            <line x1="3" y1="10" x2="21" y2="10"></line>
21	          </svg>
22	          <input type="month" id="monthPicker" class="rev-inline-input" />
23	        </label>
24	
25	        <label id="staffPickerWrap" class="rev-action-control" style="display:none;">
26	          <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
27	            <path d="M16 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2"></path>
28	            <circle cx="8.5" cy="7" r="4"></circle>
29	          </svg>
30	          <select id="staffPicker" class="rev-inline-select"></select>
31	        </label>
32	      </div>
33	    </div>
34	
35	    <div id="revBanner" class="card rev-banner-card" style="display:none;">
36	      <div class="card-body" id="revBannerText"></div>
37	    </div>
38	
39	    <div class="rev-grid">
40	      <section class="card rev-upload-card">
41	        <div class="card-header">
42	          <div>
43	            <div class="card-title">Add a Review</div>
44	            <div class="card-subtitle">Assigned to <strong id="uploadMonthLabel">this month</strong>.</div>
45	          </div>
46	        </div>
47	        <div class="card-body">
48	          <div class="rev-dropzone" id="dropzone">
49	            <input type="file" id="fileInput" accept="image/png,image/jpeg,image/webp,image/gif" hidden />
50	            <img id="previewImg" class="rev-preview" alt="Preview" style="display:none;" />
51	            <div id="dropPrompt" class="rev-drop-prompt">
52	              <svg xmlns="http://www.w3.org/2000/svg" width="30" height="30" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6">
53	                <path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"></path>
54	                <polyline points="17 8 12 3 7 8"></polyline>
55	                <line x1="12" y1="3" x2="12" y2="15"></line>
56	              </svg>
57	              <span>Tap to choose a screenshot</span>
58	              <small>PNG, JPEG, WebP or GIF — up to 10 MB</small>
59	            </div>
60	          </div>
61	
62	          <div class="form-group">
63	            <label class="form-label" for="reviewerNameInput">Reviewer name <span class="rev-optional">(optional)</span></label>
64	            <input type="text" id="reviewerNameInput" class="form-control" placeholder="e.g. Linh Nguyen" maxlength="120" />
65	          </div>
66	
67	          <div class="form-group">
68	            <label class="form-label" for="ratingInput">Rating <span class="rev-optional">(optional)</span></label>
69	            <select id="ratingInput" class="form-control">
70	              <option value="">No rating</option>
71	              <option value="5">★★★★★ (5)</option>
72	              <option value="4">★★★★ (4)</option>
73	              <option value="3">★★★ (3)</option>
74	              <option value="2">★★ (2)</option>
75	              <option value="1">★ (1)</option>
76	            </select>
77	          </div>
78	
79	          <div class="form-group">
80	            <label class="form-label" for="notesInput">Notes <span class="rev-optional">(optional)</span></label>
81	            <textarea id="notesInput" class="form-control" rows="2" maxlength="500" placeholder="Optional note"></textarea>
82	          </div>
83	
84	          <div class="rev-upload-footer">
85	            <button class="btn btn-primary" type="button" id="uploadBtn" disabled>Upload Review</button>
86	            <span id="uploadMsg" class="rev-inline-msg success" style="display:none;">Uploaded</span>
87	            <span id="uploadErr" class="rev-inline-msg error" style="display:none;"></span>
88	          </div>
89	        </div>
90	      </section>
91	
92	      <section class="card rev-gallery-card">
93	        <div class="card-header">
94	          <div>
95	            <div class="card-title">This Month's Reviews</div>
96	            <div class="card-subtitle" id="galleryMonthLabel">Loading</div>
97	          </div>
98	          <div class="rev-count-pill"><span id="galleryCount">0</span> uploaded</div>
99	        </div>
100	        <div class="card-body">
101	          <div id="galleryGrid" class="rev-gallery-grid"></div>
102	          <div id="galleryEmpty" class="rev-empty" style="display:none;">
103	            No reviews uploaded for this month yet.
104	          </div>
105	        </div>
106	      </section>
107	    </div>
108	  </div>
109	
110	  <div id="lightbox" class="rev-lightbox" style="display:none;">
111	    <img id="lightboxImg" src="" alt="Review" />
112	  </div>
113	</AdminLayout>
114	
115	<style is:global>
116	  .rev-page-shell { display:flex; flex-direction:column; gap:12px; }
117	  .rev-page-header {
118	    display:flex; align-items:flex-start; justify-content:space-between;
119	    gap:16px; flex-wrap:wrap;
120	  }
121	  .rev-page-actions { display:flex; gap:10px; flex-wrap:wrap; }
122	  .rev-action-control {
123	    display:inline-flex; align-items:center; gap:8px;
124	    background:var(--color-surface, #fff); border:1px solid var(--color-border, #e2e8f0);
125	    border-radius:10px; padding:8px 12px; color:var(--color-text-muted, #64748b);
126	    cursor:pointer;
127	  }
128	  .rev-inline-input, .rev-inline-select {
129	    border:none; background:transparent; color:var(--color-text, #0f172a);
130	    font:inherit; outline:none; cursor:pointer;
131	  }
132	  .rev-banner-card { border-left:4px solid var(--color-warning, #f59e0b); }
133	
134	  .rev-grid {
135	    display:grid; grid-template-columns:minmax(300px, 380px) 1fr; gap:16px;
136	  }
137	  @media (max-width: 880px) { .rev-grid { grid-template-columns:1fr; } }
138	
139	  .rev-dropzone {
140	    border:2px dashed var(--color-border, #cbd5e1); border-radius:14px;
141	    min-height:180px; display:flex; align-items:center; justify-content:center;
142	    text-align:center; cursor:pointer; padding:16px; margin-bottom:16px;
143	    transition:border-color .15s, background .15s;
144	  }
145	  .rev-dropzone:hover, .rev-dropzone.dragover {
146	    border-color:var(--color-primary, #6366f1);
147	    background:var(--color-primary-soft, rgba(99,102,241,.06));
148	  }
149	  .rev-drop-prompt { display:flex; flex-direction:column; align-items:center; gap:6px; color:var(--color-text-muted, #64748b); }
150	  .rev-drop-prompt small { font-size:.78rem; opacity:.8; }
151	  .rev-preview { max-width:100%; max-height:260px; border-radius:10px; object-fit:contain; }
152	
153	  .rev-optional { color:var(--color-text-muted, #94a3b8); font-weight:400; font-size:.82em; }
154	  .rev-upload-footer { display:flex; align-items:center; gap:12px; margin-top:6px; }
155	  .rev-inline-msg { font-size:.85rem; }
156	  .rev-inline-msg.success { color:var(--color-success, #16a34a); }
157	  .rev-inline-msg.error { color:var(--color-danger, #dc2626); }
158	
159	  .rev-count-pill {
160	    align-self:center; background:var(--color-primary-soft, rgba(99,102,241,.12));
161	    color:var(--color-primary, #4f46e5); border-radius:999px; padding:4px 12px;
162	    font-size:.82rem; font-weight:600; white-space:nowrap;
163	  }
164	
165	  .rev-gallery-grid {
166	    display:grid; grid-template-columns:repeat(auto-fill, minmax(160px, 1fr)); gap:14px;
167	  }
168	  .rev-tile {
169	    border:1px solid var(--color-border, #e2e8f0); border-radius:12px; overflow:hidden;
170	    display:flex; flex-direction:column; background:var(--color-surface, #fff);
171	  }
172	  .rev-tile-img {
173	    width:100%; aspect-ratio:1/1; object-fit:cover; cursor:zoom-in;
174	    background:var(--color-surface-muted, #f1f5f9);
175	  }
176	  .rev-tile-body { padding:10px 12px; display:flex; flex-direction:column; gap:4px; }
177	  .rev-tile-date { font-size:.78rem; color:var(--color-text-muted, #64748b); }
178	  .rev-tile-reviewer { font-size:.85rem; font-weight:600; color:var(--color-text, #0f172a); }
179	  .rev-tile-stars { font-size:.8rem; color:#f59e0b; letter-spacing:1px; }
180	  .rev-tile-notes { font-size:.78rem; color:var(--color-text-muted, #64748b); }
181	  .rev-status-badge {
182	    align-self:flex-start; display:inline-block; border-radius:999px;
183	    padding:2px 9px; font-size:.72rem; font-weight:600; line-height:1.4;
184	  }
185	  .rev-status-badge.pending {
186	    background:var(--color-warning-soft, rgba(245,158,11,.14)); color:var(--color-warning, #b45309);
187	  }
188	  .rev-status-badge.approved {
189	    background:var(--color-success-soft, rgba(22,163,74,.14)); color:var(--color-success, #16a34a);
190	  }
191	  .rev-status-badge.rejected {
192	    background:var(--color-danger-soft, rgba(220,38,38,.12)); color:var(--color-danger, #dc2626);
193	  }
194	  .rev-tile-actions { margin-top:6px; }
195	  .rev-tile-delete {
196	    border:none; background:transparent; color:var(--color-danger, #dc2626);
197	    font-size:.78rem; cursor:pointer; padding:0;
198	  }
199	  .rev-tile-delete:hover { text-decoration:underline; }
200	
201	  .rev-empty { text-align:center; color:var(--color-text-muted, #94a3b8); padding:30px 10px; }
202	
203	  .rev-lightbox {
204	    position:fixed; inset:0; background:rgba(0,0,0,.8); z-index:1000;
205	    display:grid; place-items:center; padding:24px; cursor:zoom-out;
206	  }
207	  .rev-lightbox img { max-width:min(92vw, 900px); max-height:90vh; border-radius:10px; }
208	</style>
209	
210	<script>
211	  const API = import.meta.env.PUBLIC_API_URL;
212	  const token = localStorage.getItem("token");
213	
214	  const monthPicker = document.getElementById("monthPicker");
215	  const staffPicker = document.getElementById("staffPicker");
216	  const staffPickerWrap = document.getElementById("staffPickerWrap");
217	  const fileInput = document.getElementById("fileInput");
218	  const dropzone = document.getElementById("dropzone");
219	  const previewImg = document.getElementById("previewImg");
220	  const dropPrompt = document.getElementById("dropPrompt");
221	  const uploadBtn = document.getElementById("uploadBtn");
222	
223	  let isAdmin = false;
224	  let selectedFile = null;
225	
226	  function parseJwtPayload(rawToken) {
227	    try {
228	      const segment = rawToken?.split(".")?.[1];
229	      if (!segment) return {};
230	      const normalized = segment
231	        .replaceAll("-", "+")
232	        .replaceAll("_", "/")
233	        .padEnd(Math.ceil(segment.length / 4) * 4, "=");
234	      return JSON.parse(atob(normalized));
235	    } catch {
236	      return {};
237	    }
238	  }
239	
240	  function escapeHtml(value) {
241	    return String(value ?? "")
242	      .replaceAll("&", "&amp;")
243	      .replaceAll("<", "&lt;")
244	      .replaceAll(">", "&gt;")
245	      .replaceAll('"', "&quot;")
246	      .replaceAll("'", "&#39;");
247	  }
248	
249	  function statusBadge(status) {
250	    const s = (status || "Pending");
251	    const cls = s === "Approved" ? "approved" : s === "Rejected" ? "rejected" : "pending";
252	    return `<span class="rev-status-badge ${cls}">${escapeHtml(s)}</span>`;
253	  }
254	
255	  function setMonthDefault() {
256	    const now = new Date();
257	    monthPicker.value = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, "0")}`;
258	  }
259	
260	  function selectedYearMonth() {
261	    const [year, month] = (monthPicker.value || "").split("-").map(Number);
262	    return { year, month };
263	  }
264	
265	  function monthLabel() {
266	    const { year, month } = selectedYearMonth();
267	    if (!year || !month) return "this month";
268	    return new Date(year, month - 1, 1).toLocaleDateString(undefined, { month: "long", year: "numeric" });
269	  }
270	
271	  function formatDate(iso) {
272	    if (!iso) return "";
273	    const d = new Date(iso);
274	    if (isNaN(d.getTime())) return "";
275	    return d.toLocaleDateString(undefined, { year: "numeric", month: "short", day: "numeric" });
276	  }
277	
278	  function showBanner(message) {
279	    const banner = document.getElementById("revBanner");
280	    document.getElementById("revBannerText").textContent = message;
281	    banner.style.display = message ? "" : "none";
282	  }
283	
284	  async function loadRole() {
285	    const payload = parseJwtPayload(token);
286	    const role = (
287	      payload["http://schemas.microsoft.com/ws/2008/06/identity/claims/role"] ||
288	      payload.role ||
289	      ""
290	    ).toLowerCase();
291	    isAdmin = role === "admin";
292	    staffPickerWrap.style.display = isAdmin ? "" : "none";
293	    if (isAdmin) await loadReceptionists();
294	  }
295	
296	  // Reuse the KPI dashboard endpoint to enumerate receptionists for the admin picker.
297	  async function loadReceptionists() {
298	    try {
299	      const { year, month } = selectedYearMonth();
300	      const res = await fetch(`${API}/api/receptionist-kpi/dashboard?year=${year}&month=${month}`, {
301	        headers: { Authorization: `Bearer ${token}` },
302	      });
303	      const data = await res.json().catch(() => ({}));
304	      if (!res.ok) return;
305	      const list = data.receptionists || [];
306	      const current = staffPicker.value;
307	      staffPicker.innerHTML = list
308	        .map((s) => `<option value="${escapeHtml(s.id)}">${escapeHtml(s.name)}</option>`)
309	        .join("");
310	      if (current && list.some((s) => s.id === current)) staffPicker.value = current;
311	    } catch { /* ignore */ }
312	  }
313	
314	  function currentStaffId() {
315	    return isAdmin && staffPicker.value ? staffPicker.value : null;
316	  }
317	
318	  function setSelectedFile(file) {
319	    selectedFile = file || null;
320	    if (selectedFile) {
321	      previewImg.src = URL.createObjectURL(selectedFile);
322	      previewImg.style.display = "";
323	      dropPrompt.style.display = "none";
324	    } else {
325	      previewImg.removeAttribute("src");
326	      previewImg.style.display = "none";
327	      dropPrompt.style.display = "";
328	    }
329	    uploadBtn.disabled = !selectedFile;
330	  }
331	
332	  function wireDropzone() {
333	    dropzone.addEventListener("click", () => fileInput.click());
334	    fileInput.addEventListener("change", () => setSelectedFile(fileInput.files?.[0] || null));
335	    ["dragenter", "dragover"].forEach((evt) =>
336	      dropzone.addEventListener(evt, (e) => { e.preventDefault(); dropzone.classList.add("dragover"); }));
337	    ["dragleave", "drop"].forEach((evt) =>
338	      dropzone.addEventListener(evt, (e) => { e.preventDefault(); dropzone.classList.remove("dragover"); }));
339	    dropzone.addEventListener("drop", (e) => {
340	      const file = e.dataTransfer?.files?.[0];
341	      if (file) setSelectedFile(file);
342	    });
343	  }
344	
345	  async function uploadReview() {
346	    if (!selectedFile) return;
347	    const ok = document.getElementById("uploadMsg");
348	    const err = document.getElementById("uploadErr");
349	    ok.style.display = "none";
350	    err.style.display = "none";
351	    uploadBtn.disabled = true;
352	
353	    try {
354	      const { year, month } = selectedYearMonth();
355	      if (!year || !month) throw new Error("Pick a month first.");
356	
357	      const fd = new FormData();
358	      fd.append("file", selectedFile, selectedFile.name);
359	      fd.append("year", String(year));
360	      fd.append("month", String(month));
361	      const staffId = currentStaffId();
362	      if (staffId) fd.append("staffId", staffId);
363	      const reviewerName = document.getElementById("reviewerNameInput").value.trim();
364	      if (reviewerName) fd.append("reviewerName", reviewerName);
365	      const rating = document.getElementById("ratingInput").value;
366	      if (rating) fd.append("rating", rating);
367	      const notes = document.getElementById("notesInput").value.trim();
368	      if (notes) fd.append("notes", notes);
369	
370	      const res = await fetch(`${API}/api/review-uploads`, {
371	        method: "POST",
372	        headers: { Authorization: `Bearer ${token}` },
373	        body: fd,
374	      });
375	      const data = await res.json().catch(() => ({}));
376	      if (!res.ok) throw new Error(data.message || `Upload failed (HTTP ${res.status})`);
377	
378	      ok.style.display = "";
379	      setTimeout(() => { ok.style.display = "none"; }, 2000);
380	      // Reset the form.
381	      setSelectedFile(null);
382	      fileInput.value = "";
383	      document.getElementById("reviewerNameInput").value = "";
384	      document.getElementById("ratingInput").value = "";
385	      document.getElementById("notesInput").value = "";
386	      await loadGallery();
387	    } catch (error) {
388	      err.textContent = error.message || "Upload failed.";
389	      err.style.display = "";
390	    } finally {
391	      uploadBtn.disabled = !selectedFile;
392	    }
393	  }
394	
395	  async function loadGallery() {
396	    const { year, month } = selectedYearMonth();
397	    if (!year || !month) return;
398	    document.getElementById("galleryMonthLabel").textContent = monthLabel();
399	    document.getElementById("uploadMonthLabel").textContent = monthLabel();
400	
401	    const params = new URLSearchParams({ year: String(year), month: String(month) });
402	    const staffId = currentStaffId();
403	    if (staffId) params.set("staffId", staffId);
404	
405	    try {
406	      const res = await fetch(`${API}/api/review-uploads?${params.toString()}`, {
407	        headers: { Authorization: `Bearer ${token}` },
408	      });
409	      const data = await res.json().catch(() => ({}));
410	      if (!res.ok) throw new Error(data.message || `Failed to load reviews (${res.status})`);
411	      renderGallery(data);
412	    } catch (error) {
413	      showBanner(error.message || "Failed to load reviews.");
414	    }
415	  }
416	
417	  function renderGallery(data) {
418	    const grid = document.getElementById("galleryGrid");
419	    const empty = document.getElementById("galleryEmpty");
420	    const items = data.items || [];
421	    document.getElementById("galleryCount").textContent = String(data.count ?? items.length);
422	
423	    if (items.length === 0) {
424	      grid.innerHTML = "";
425	      empty.style.display = "";
426	      return;
427	    }
428	    empty.style.display = "none";
429	
430	    grid.innerHTML = items.map((item) => {
431	      const stars = item.rating ? "★".repeat(item.rating) + "☆".repeat(5 - item.rating) : "";
432	      return `
433	        <div class="rev-tile">
434	          <img class="rev-tile-img" src="${escapeHtml(item.imageUrl)}" alt="Review" loading="lazy" data-full="${escapeHtml(item.imageUrl)}" />
435	          <div class="rev-tile-body">
436	            <div class="rev-tile-date">Added ${escapeHtml(formatDate(item.uploadedAt))}</div>
437	            ${statusBadge(item.status)}
438	            ${item.reviewerName ? `<div class="rev-tile-reviewer">${escapeHtml(item.reviewerName)}</div>` : ""}
439	            ${stars ? `<div class="rev-tile-stars">${stars}</div>` : ""}
440	            ${item.notes ? `<div class="rev-tile-notes">${escapeHtml(item.notes)}</div>` : ""}
441	            ${item.status === "Rejected" && item.rejectionReason ? `<div class="rev-tile-notes">Reason: ${escapeHtml(item.rejectionReason)}</div>` : ""}
442	            <div class="rev-tile-actions">
443	              <button type="button" class="rev-tile-delete" data-delete-id="${escapeHtml(item.id)}">Delete</button>
444	            </div>
445	          </div>
446	        </div>`;
447	    }).join("");
448	
449	    grid.querySelectorAll("[data-full]").forEach((img) =>
450	      img.addEventListener("click", () => openLightbox(img.dataset.full)));
451	    grid.querySelectorAll("[data-delete-id]").forEach((btn) =>
452	      btn.addEventListener("click", () => deleteReview(btn.dataset.deleteId)));
453	  }
454	
455	  async function deleteReview(id) {
456	    if (!id) return;
457	    if (!confirm("Delete this review upload? This cannot be undone.")) return;
458	    try {
459	      const res = await fetch(`${API}/api/review-uploads/${id}`, {
460	        method: "DELETE",
461	        headers: { Authorization: `Bearer ${token}` },
462	      });
463	      if (!res.ok && res.status !== 204) {
464	        const data = await res.json().catch(() => ({}));
465	        throw new Error(data.message || `Delete failed (${res.status})`);
466	      }
467	      await loadGallery();
468	    } catch (error) {
469	      showBanner(error.message || "Delete failed.");
470	    }
471	  }
472	
473	  function openLightbox(url) {
474	    const box = document.getElementById("lightbox");
475	    document.getElementById("lightboxImg").src = url;
476	    box.style.display = "grid";
477	  }
478	  document.getElementById("lightbox").addEventListener("click", (e) => {
479	    e.currentTarget.style.display = "none";
480	    document.getElementById("lightboxImg").removeAttribute("src");
481	  });
482	
483	  monthPicker.addEventListener("change", async () => {
484	    if (isAdmin) await loadReceptionists();
485	    await loadGallery();
486	  });
487	  staffPicker.addEventListener("change", loadGallery);
488	  uploadBtn.addEventListener("click", uploadReview);
489	
490	  setMonthDefault();
491	  wireDropzone();
492	
493	  (async function init() {
494	    try {
495	      await loadRole();
496	      await loadGallery();
497	    } catch (error) {
498	      showBanner(error.message || "Failed to load review uploads page.");
499	    }
500	  })();
501	</script>
