4	
5	<AdminLayout title="Review Approvals" activePage="review-approvals">
6	  <div class="rev-page-shell">
7	    <div class="rev-page-header">
8	      <div>
9	        <div class="page-title">Review Approvals</div>
10	        <div class="page-subtitle">
