117	<script>
118	  const API = import.meta.env.PUBLIC_API_URL;
119	  const token = localStorage.getItem("token");
120	
121	  const monthPicker = document.getElementById("monthPicker");
122	  let filterByMonth = true;
123	
124	  function escapeHtml(value) {
125	    return String(value ?? "")
126	      .replaceAll("&", "&amp;")
127	      .replaceAll("<", "&lt;")
128	      .replaceAll(">", "&gt;")
129	      .replaceAll('"', "&quot;")
130	      .replaceAll("'", "&#39;");
131	  }
132	
133	  function setMonthDefault() {
134	    const now = new Date();
135	    monthPicker.value = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, "0")}`;
136	  }
137	
138	  function selectedYearMonth() {
139	    const [year, month] = (monthPicker.value || "").split("-").map(Number);
140	    return { year, month };
141	  }
142	
143	  function queueLabelText() {
144	    if (!filterByMonth) return "All months";
145	    const { year, month } = selectedYearMonth();
146	    if (!year || !month) return "All months";
147	    return new Date(year, month - 1, 1).toLocaleDateString(undefined, { month: "long", year: "numeric" });
148	  }
149	
150	  function formatDate(iso) {
151	    if (!iso) return "";
152	    const d = new Date(iso);
153	    if (isNaN(d.getTime())) return "";
154	    return d.toLocaleDateString(undefined, { year: "numeric", month: "short", day: "numeric" });
155	  }
156	
157	  function showBanner(message) {
158	    const banner = document.getElementById("revBanner");
159	    document.getElementById("revBannerText").textContent = message || "";
160	    banner.style.display = message ? "" : "none";
161	  }
162	
163	  async function loadQueue() {
164	    document.getElementById("queueLabel").textContent = queueLabelText();
165	    const params = new URLSearchParams();
166	    if (filterByMonth) {
167	      const { year, month } = selectedYearMonth();
168	      if (year && month) { params.set("year", String(year)); params.set("month", String(month)); }
169	    }
170	    try {
171	      const res = await fetch(`${API}/api/review-uploads/pending?${params.toString()}`, {
172	        headers: { Authorization: `Bearer ${token}` },
173	      });
174	      const data = await res.json().catch(() => ({}));
175	      if (!res.ok) throw new Error(data.message || `Failed to load pending reviews (${res.status})`);
176	      showBanner("");
177	      renderQueue(data);
178	    } catch (error) {
179	      showBanner(error.message || "Failed to load pending reviews.");
180	    }
181	  }
182	
183	  function renderQueue(data) {
184	    const grid = document.getElementById("queueGrid");
185	    const empty = document.getElementById("queueEmpty");
186	    const items = data.items || [];
187	    document.getElementById("queueCount").textContent = String(data.count ?? items.length);
188	
189	    if (items.length === 0) {
190	      grid.innerHTML = "";
191	      empty.style.display = "";
192	      return;
193	    }
194	    empty.style.display = "none";
195	
196	    grid.innerHTML = items.map((item) => {
197	      const stars = item.rating ? "★".repeat(item.rating) + "☆".repeat(5 - item.rating) : "";
198	      const period = new Date(item.year, item.month - 1, 1)
199	        .toLocaleDateString(undefined, { month: "short", year: "numeric" });
200	      return `
201	        <div class="rev-tile">
202	          <img class="rev-tile-img" src="${escapeHtml(item.imageUrl)}" alt="Review" loading="lazy" data-full="${escapeHtml(item.imageUrl)}" />
203	          <div class="rev-tile-body">
204	            <div class="rev-tile-staff">${escapeHtml(item.staffName || "Receptionist")}</div>
205	            <div class="rev-tile-date">Added ${escapeHtml(formatDate(item.uploadedAt))} · ${escapeHtml(period)}</div>
206	            ${item.reviewerName ? `<div class="rev-tile-reviewer">${escapeHtml(item.reviewerName)}</div>` : ""}
207	            ${stars ? `<div class="rev-tile-stars">${stars}</div>` : ""}
208	            ${item.notes ? `<div class="rev-tile-notes">${escapeHtml(item.notes)}</div>` : ""}
209	            <div class="rev-approve-actions">
210	              <button type="button" class="btn rev-btn-approve" data-approve-id="${escapeHtml(item.id)}">Approve</button>
211	              <button type="button" class="btn rev-btn-reject" data-reject-id="${escapeHtml(item.id)}">Reject</button>
212	            </div>
213	          </div>
214	        </div>`;
215	    }).join("");
216	
217	    grid.querySelectorAll("[data-full]").forEach((img) =>
218	      img.addEventListener("click", () => openLightbox(img.dataset.full)));
219	    grid.querySelectorAll("[data-approve-id]").forEach((btn) =>
220	      btn.addEventListener("click", () => decide(btn.dataset.approveId, "approve")));
221	    grid.querySelectorAll("[data-reject-id]").forEach((btn) =>
222	      btn.addEventListener("click", () => decide(btn.dataset.rejectId, "reject")));
223	  }
224	
225	  async function decide(id, action) {
226	    if (!id) return;
227	    let body;
228	    if (action === "reject") {
229	      const reason = prompt("Optional reason for rejecting this review:", "");
230	      if (reason === null) return; // cancelled
231	      body = JSON.stringify({ reason });
232	    }
233	    try {
234	      const res = await fetch(`${API}/api/review-uploads/${id}/${action}`, {
235	        method: "POST",
236	        headers: {
237	          Authorization: `Bearer ${token}`,
238	          "Content-Type": "application/json",
239	        },
240	        body: body ?? "{}",
241	      });
242	      if (!res.ok) {
243	        const data = await res.json().catch(() => ({}));
244	        throw new Error(data.message || `${action} failed (${res.status})`);
245	      }
246	      await loadQueue();
247	    } catch (error) {
248	      showBanner(error.message || `${action} failed.`);
249	    }
250	  }
251	
252	  function openLightbox(url) {
253	    const box = document.getElementById("lightbox");
254	    document.getElementById("lightboxImg").src = url;
255	    box.style.display = "grid";
256	  }
257	  document.getElementById("lightbox").addEventListener("click", (e) => {
258	    e.currentTarget.style.display = "none";
259	    document.getElementById("lightboxImg").removeAttribute("src");
260	  });
261	
262	  monthPicker.addEventListener("change", () => { filterByMonth = true; loadQueue(); });
263	  document.getElementById("clearMonthBtn").addEventListener("click", () => { filterByMonth = false; loadQueue(); });
264	
265	  setMonthDefault();
266	  (async function init() {
267	    try {
268	      await loadQueue();
269	    } catch (error) {
270	      showBanner(error.message || "Failed to load review approvals page.");
271	    }
272	  })();
273	</script>
