199	        var t = el.getAttribute('type');
200	        if (t === 'datetime-local') {
201	          flatpickr(el, { enableTime: true, dateFormat: 'Y-m-dTH:i', allowInput: true, time_24hr: true, disableMobile: true });
202	        } else if (t === 'time') {
203	          flatpickr(el, { enableTime: true, noCalendar: true, dateFormat: 'H:i', allowInput: true, time_24hr: true, disableMobile: true });
204	        } else {
205	          flatpickr(el, { dateFormat: 'Y-m-d', allowInput: true, disableMobile: true });
206	        }
207	      }
208	
209	      var obs = null;
210	      function initFP() {
211	        if (!window.flatpickr) return;
212	        var els = document.querySelectorAll(SELECTOR);
213	        if (!els.length) return;
214	        // Detach while we mutate the DOM so flatpickr's inserted nodes don't
215	        // feed back into the observer.
216	        if (obs) obs.disconnect();
217	        els.forEach(initOne);
218	        if (obs) obs.observe(document.body, { childList: true, subtree: true });
219	      }
220	
221	      // Initial run
222	      if (window.flatpickr) { initFP(); }
223	      else {
224	        var fp = document.querySelector('script[src*="flatpickr"]');
225	        if (fp) fp.addEventListener('load', initFP);
226	      }
227	
228	      // Re-run on dynamic content (modals, forms injected after load), but only
229	      // when a date-type input actually appeared, and coalesced to one pass per
230	      // frame instead of one per mutation.
231	      var scheduled = false;
232	      function schedule() {
233	        if (scheduled) return;
234	        scheduled = true;
235	        (window.requestAnimationFrame || window.setTimeout)(function () {
236	          scheduled = false;
237	          initFP();
238	        }, 0);
239	      }
240	      obs = new MutationObserver(function (mutations) {
241	        for (var i = 0; i < mutations.length; i++) {
242	          var added = mutations[i].addedNodes;
243	          for (var j = 0; j < added.length; j++) {
244	            var n = added[j];
245	            if (n.nodeType !== 1) continue;
246	            if ((n.matches && n.matches('input[type="date"],input[type="datetime-local"],input[type="time"]')) ||
247	                (n.querySelector && n.querySelector('input[type="date"],input[type="datetime-local"],input[type="time"]'))) {
248	              schedule();
249	              return;
250	            }
251	          }
252	        }
253	      });
254	      obs.observe(document.body, { childList: true, subtree: true });
255	    });
256	  </script>
