501	    <script is:inline>
502	      (function () {
503	        const input = document.getElementById('clientSearchInput');
504	        const box = document.getElementById('clientSearchResults');
505	        const wrap = document.getElementById('clientQuickSearch');
506	        if (!input || !box) return;
507	        const apiEl = document.querySelector('[data-api-base]');
508	        const API = apiEl && apiEl.dataset ? (apiEl.dataset.apiBase || '') : '';
509	        const tok = () => localStorage.getItem('token') || '';
510	        const esc = (s) => String(s == null ? '' : s).replace(/[&<>"']/g, m => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
511	        const colors = ['#c8a45d','#4a90d9','#5cb85c','#d9534f','#8e5bd9','#d98c3f'];
512	        let timer = null, lastQ = '';
513	
514	        function close() { box.classList.remove('open'); box.innerHTML = ''; }
515	        const ICO = {
516	          phone: '<svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M22 16.92v3a2 2 0 0 1-2.18 2 19.8 19.8 0 0 1-8.63-3.07 19.5 19.5 0 0 1-6-6A19.8 19.8 0 0 1 2.12 4.18 2 2 0 0 1 4.11 2h3a2 2 0 0 1 2 1.72c.13.96.36 1.9.7 2.81a2 2 0 0 1-.45 2.11L8.09 9.91a16 16 0 0 0 6 6l1.27-1.27a2 2 0 0 1 2.11-.45c.91.34 1.85.57 2.81.7A2 2 0 0 1 22 16.92z"/></svg>',
517	          mail: '<svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="2" y="4" width="20" height="16" rx="2"/><path d="m22 7-10 6L2 7"/></svg>',
518	          chev: '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="9 18 15 12 9 6"/></svg>',
519	          search: '<svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="11" cy="11" r="8"/><line x1="21" y1="21" x2="16.65" y2="16.65"/></svg>',
520	          grp: '<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><path d="M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M23 21v-2a4 4 0 0 0-3-3.87M16 3.13a4 4 0 0 1 0 7.75"/></svg>',
521	          pvt: '<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><path d="M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2"/><circle cx="12" cy="7" r="4"/></svg>',
522	          mat: '<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="6" width="18" height="12" rx="2"/><path d="M3 12h18"/></svg>',
523	        };
524	        function render(list, q) {
525	          if (!list.length) { box.innerHTML = '<div class="cqs-empty">No clients found for “' + esc(q) + '”</div>'; box.classList.add('open'); return; }
526	          const total = list.length, shown = Math.min(4, total);
527	          const rows = list.slice(0, 4).map((c, i) => {
528	            const initials = (c.name || '?').split(' ').filter(Boolean).map(w => w[0]).join('').substring(0, 2).toUpperCase();
529	            const phone = [c.phoneCountryCode, c.phone].filter(Boolean).join(' ');
530	            const bits = [];
531	            if (phone) bits.push(ICO.phone + '<span>' + esc(phone) + '</span>');
532	            if (c.email) bits.push('<span class="sep">•</span>' + ICO.mail + '<span>' + esc(c.email) + '</span>');
533	            const contact = bits.length ? bits.join(' ') : '<span>No contact details</span>';
534	            return '<a class="cqs-item" href="/admin/client-profile?id=' + encodeURIComponent(c.id) + '">'
535	              + '<span class="cqs-av" style="background:' + colors[i % colors.length] + '">' + esc(initials) + '</span>'
536	              + '<div class="cqs-main"><div class="cqs-name">' + esc(c.name) + '</div><div class="cqs-contact">' + contact + '</div></div>'
537	              + '<div class="cqs-pkgs"><div class="lbl">Packages</div><div class="cqs-badges">'
538	              + '<span class="cqs-b grp">Group ' + (c.groupCredits || 0) + '</span>'
539	              + '<span class="cqs-b pvt">Private ' + (c.privateCredits || 0) + '</span>'
540	              + '<span class="cqs-b mat">Mat ' + (c.matCredits || 0) + '</span>'
541	              + '</div></div><span class="cqs-chev">' + ICO.chev + '</span></a>';
542	          }).join('');
543	          const head = '<div class="cqs-head"><span class="t">Top results</span><span class="n">Showing ' + shown + ' of ' + total + '</span></div>';
544	          const more = total > 4 ? '<a class="cqs-more" href="/admin/clients?search=' + encodeURIComponent(q) + '">' + ICO.search + ' View all ' + total + ' results →</a>' : '';
545	          const legend = '<div class="cqs-legend">'
546	            + '<div class="grp">' + ICO.grp + '<div><div class="lg-t">Group</div><div class="lg-d">Group classes</div></div></div>'
547	            + '<div class="pvt">' + ICO.pvt + '<div><div class="lg-t">Private</div><div class="lg-d">Private sessions</div></div></div>'
548	            + '<div class="mat">' + ICO.mat + '<div><div class="lg-t">Mat</div><div class="lg-d">Mat classes</div></div></div>'
549	            + '</div>';
550	          box.innerHTML = head + rows + more + legend;
551	          box.classList.add('open');
552	        }
553	        async function run(q) {
554	          try {
555	            const res = await fetch(API + '/api/client?sort=recent&search=' + encodeURIComponent(q), { headers: { Authorization: 'Bearer ' + tok() } });
556	            if (!res.ok) { close(); return; }
557	            const list = await res.json();
558	            if (q !== lastQ) return;
559	            render(Array.isArray(list) ? list : [], q);
560	          } catch (e) { close(); }
561	        }
562	        input.addEventListener('input', function () {
563	          const q = input.value.trim();
564	          lastQ = q;
565	          if (timer) clearTimeout(timer);
566	          if (q.length < 2) { close(); return; }
567	          timer = setTimeout(function () { run(q); }, 250);
568	        });
569	        input.addEventListener('focus', function () { if (input.value.trim().length >= 2 && box.innerHTML) box.classList.add('open'); });
570	        document.addEventListener('click', function (e) { if (wrap && !wrap.contains(e.target)) close(); });
571	        document.addEventListener('keydown', function (e) { if (e.key === 'Escape') { close(); input.blur(); } });
572	      })();
573	    </script>
