1770	  function renderProjectionChart(currentPercent, forecastPercent) {
1771	    const current = Math.max(0, Math.min(100, Number(currentPercent || 0)));
1772	    const forecast = Math.max(current, Math.min(100, Number(forecastPercent || 0)));
1773	    const values = [
1774	      Math.max(4, current * 0.22),
1775	      Math.max(8, current * 0.4),
1776	      Math.max(12, current * 0.46),
1777	      Math.max(16, current * 0.58),
1778	      Math.max(22, current * 0.68),
1779	      Math.max(28, current * 0.8),
1780	      current,
1781	      Math.max(current, (current + forecast) / 2),
1782	      forecast,
1783	    ].map((value) => Math.max(0, Math.min(100, value)));
1784	
1785	    const width = 320;
1786	    const height = 120;
1787	    const step = width / (values.length - 1);
1788	    const points = values.map((value, index) => {
1789	      const x = index * step;
1790	      const y = 110 - (value / 100) * 94;
1791	      return [x, y];
1792	    });
1793	
1794	    const linePath = points.map(([x, y], index) => `${index === 0 ? "M" : "L"} ${x.toFixed(2)} ${y.toFixed(2)}`).join(" ");
1795	    const areaPath = `${linePath} L ${width} 112 L 0 112 Z`;
1796	    const guidePoint = points[points.length - 2];
1797	    const dotPoint = points[points.length - 1];
1798	
1799	    document.getElementById("projectionLine").setAttribute("d", linePath);
1800	    document.getElementById("projectionArea").setAttribute("d", areaPath);
1801	    document.getElementById("projectionGuideLine").setAttribute("x1", guidePoint[0].toFixed(2));
1802	    document.getElementById("projectionGuideLine").setAttribute("x2", guidePoint[0].toFixed(2));
1803	    document.getElementById("projectionGuideDot").setAttribute("cx", dotPoint[0].toFixed(2));
