/* ── Google Reviews: uploads + gallery + admin approvals ────────────────────
   Reuses this page's month (monthPicker) and admin staff pick (staffPicker),
   plus the shared isAdmin / escapeHtml / selectedYearMonth helpers, so the
   review controls track the exact period being viewed. Hits the same backend
   as the old standalone pages: /api/review-uploads (+ /pending, /approve,
   /reject). All review-only identifiers are `rev`-prefixed to avoid clashes
   with the KPI dashboard code above. */
const revFileInput = document.getElementById("fileInput");
const revDropzone = document.getElementById("dropzone");
const revPreviewImg = document.getElementById("previewImg");
const revDropPrompt = document.getElementById("dropPrompt");
const revUploadBtn = document.getElementById("uploadBtn");
let revSelectedFile = null;

function revMonthLabel() {
  const { year, month } = selectedYearMonth();
  if (!year || !month) return "this month";
  return new Date(year, month - 1, 1).toLocaleDateString(undefined, { month: "long", year: "numeric" });
}

function revFormatDate(iso) {
  if (!iso) return "";
  const d = new Date(iso);
  if (isNaN(d.getTime())) return "";
  return d.toLocaleDateString(undefined, { year: "numeric", month: "short", day: "numeric" });
}

function revShowBanner(message) {
  const banner = document.getElementById("revBanner");
  if (!banner) return;
  document.getElementById("revBannerText").textContent = message || "";
  banner.style.display = message ? "" : "none";
}

function revStatusBadge(status) {
  const s = status || "Pending";
  const cls = s === "Approved" ? "approved" : s === "Rejected" ? "rejected" : "pending";
  return `<span class="rev-status-badge ${cls}">${escapeHtml(s)}</span>`;
}

// Admin uploads/views on behalf of the picked receptionist; reception acts as self.
function revCurrentStaffId() {
  return isAdmin && staffPicker.value ? staffPicker.value : null;
}

function revSetSelectedFile(file) {
  revSelectedFile = file || null;
  if (revSelectedFile) {
    revPreviewImg.src = URL.createObjectURL(revSelectedFile);
    revPreviewImg.style.display = "";
    revDropPrompt.style.display = "none";
  } else {
    revPreviewImg.removeAttribute("src");
    revPreviewImg.style.display = "none";
    revDropPrompt.style.display = "";
  }
  revUploadBtn.disabled = !revSelectedFile;
}

function revWireDropzone() {
  revDropzone.addEventListener("click", () => revFileInput.click());
  revFileInput.addEventListener("change", () => revSetSelectedFile(revFileInput.files?.[0] || null));
  ["dragenter", "dragover"].forEach((evt) =>
    revDropzone.addEventListener(evt, (e) => { e.preventDefault(); revDropzone.classList.add("dragover"); }));
  ["dragleave", "drop"].forEach((evt) =>
    revDropzone.addEventListener(evt, (e) => { e.preventDefault(); revDropzone.classList.remove("dragover"); }));
  revDropzone.addEventListener("drop", (e) => {
    const file = e.dataTransfer?.files?.[0];
    if (file) revSetSelectedFile(file);
  });
}

async function revUploadReview() {
  if (!revSelectedFile) return;
  const ok = document.getElementById("uploadMsg");
  const err = document.getElementById("uploadErr");
  ok.style.display = "none";
  err.style.display = "none";
  revUploadBtn.disabled = true;
  try {
    const { year, month } = selectedYearMonth();
    if (!year || !month) throw new Error("Pick a month first.");

    const fd = new FormData();
    fd.append("file", revSelectedFile, revSelectedFile.name);
    fd.append("year", String(year));
    fd.append("month", String(month));
    const staffId = revCurrentStaffId();
    if (staffId) fd.append("staffId", staffId);
    const reviewerName = document.getElementById("reviewerNameInput").value.trim();
    if (reviewerName) fd.append("reviewerName", reviewerName);
    const rating = document.getElementById("ratingInput").value;
    if (rating) fd.append("rating", rating);
    const notes = document.getElementById("notesInput").value.trim();
    if (notes) fd.append("notes", notes);

    const res = await fetch(`${API}/api/review-uploads`, {
      method: "POST",
      headers: { Authorization: `Bearer ${token}` },
      body: fd,
    });
    const data = await res.json().catch(() => ({}));
    if (!res.ok) throw new Error(data.message || `Upload failed (HTTP ${res.status})`);

    ok.style.display = "";
    setTimeout(() => { ok.style.display = "none"; }, 2000);
    revSetSelectedFile(null);
    revFileInput.value = "";
    document.getElementById("reviewerNameInput").value = "";
    document.getElementById("ratingInput").value = "";
    document.getElementById("notesInput").value = "";
    await revLoadGallery();
    if (isAdmin) await revLoadQueue();
  } catch (error) {
    err.textContent = error.message || "Upload failed.";
    err.style.display = "";
  } finally {
    revUploadBtn.disabled = !revSelectedFile;
  }
}

async function revLoadGallery() {
  const { year, month } = selectedYearMonth();
  if (!year || !month) return;
  document.getElementById("galleryMonthLabel").textContent = revMonthLabel();
  document.getElementById("uploadMonthLabel").textContent = revMonthLabel();

  const params = new URLSearchParams({ year: String(year), month: String(month) });
  const staffId = revCurrentStaffId();
  if (staffId) params.set("staffId", staffId);

  try {
    const res = await fetch(`${API}/api/review-uploads?${params.toString()}`, {
      headers: { Authorization: `Bearer ${token}` },
    });
    const data = await res.json().catch(() => ({}));
    if (!res.ok) throw new Error(data.message || `Failed to load reviews (${res.status})`);
    revRenderGallery(data);
  } catch (error) {
    revShowBanner(error.message || "Failed to load reviews.");
  }
}

function revRenderGallery(data) {
  const grid = document.getElementById("galleryGrid");
  const empty = document.getElementById("galleryEmpty");
  const items = data.items || [];
  document.getElementById("galleryCount").textContent = String(data.count ?? items.length);

  if (items.length === 0) {
    grid.innerHTML = "";
    empty.style.display = "";
    return;
  }
  empty.style.display = "none";

  grid.innerHTML = items.map((item) => {
    const stars = item.rating ? "★".repeat(item.rating) + "☆".repeat(5 - item.rating) : "";
    return `
      <div class="rev-tile">
        <img class="rev-tile-img" src="${escapeHtml(item.imageUrl)}" alt="Review" loading="lazy" data-full="${escapeHtml(item.imageUrl)}" />
        <div class="rev-tile-body">
          <div class="rev-tile-date">Added ${escapeHtml(revFormatDate(item.uploadedAt))}</div>
          ${revStatusBadge(item.status)}
          ${item.reviewerName ? `<div class="rev-tile-reviewer">${escapeHtml(item.reviewerName)}</div>` : ""}
          ${stars ? `<div class="rev-tile-stars">${stars}</div>` : ""}
          ${item.notes ? `<div class="rev-tile-notes">${escapeHtml(item.notes)}</div>` : ""}
          ${item.status === "Rejected" && item.rejectionReason ? `<div class="rev-tile-notes">Reason: ${escapeHtml(item.rejectionReason)}</div>` : ""}
          <div class="rev-tile-actions">
            <button type="button" class="rev-tile-delete" data-delete-id="${escapeHtml(item.id)}">Delete</button>
          </div>
        </div>
      </div>`;
  }).join("");

  grid.querySelectorAll("[data-full]").forEach((img) =>
    img.addEventListener("click", () => revOpenLightbox(img.dataset.full)));
  grid.querySelectorAll("[data-delete-id]").forEach((btn) =>
    btn.addEventListener("click", () => revDeleteReview(btn.dataset.deleteId)));
}

async function revDeleteReview(id) {
  if (!id) return;
  if (!confirm("Delete this review upload? This cannot be undone.")) return;
  try {
    const res = await fetch(`${API}/api/review-uploads/${id}`, {
      method: "DELETE",
      headers: { Authorization: `Bearer ${token}` },
    });
    if (!res.ok && res.status !== 204) {
      const data = await res.json().catch(() => ({}));
      throw new Error(data.message || `Delete failed (${res.status})`);
    }
    await revLoadGallery();
    if (isAdmin) await revLoadQueue();
  } catch (error) {
    revShowBanner(error.message || "Delete failed.");
  }
}

// Admin-only approvals queue for the selected month.
async function revLoadQueue() {
  if (!isAdmin) return;
  const { year, month } = selectedYearMonth();
  document.getElementById("queueLabel").textContent = revMonthLabel();
  const params = new URLSearchParams();
  if (year && month) { params.set("year", String(year)); params.set("month", String(month)); }
  try {
    const res = await fetch(`${API}/api/review-uploads/pending?${params.toString()}`, {
      headers: { Authorization: `Bearer ${token}` },
    });
    const data = await res.json().catch(() => ({}));
    if (!res.ok) throw new Error(data.message || `Failed to load pending reviews (${res.status})`);
    revRenderQueue(data);
  } catch (error) {
    revShowBanner(error.message || "Failed to load pending reviews.");
  }
}

function revRenderQueue(data) {
  const grid = document.getElementById("queueGrid");
  const empty = document.getElementById("queueEmpty");
  const items = data.items || [];
  document.getElementById("queueCount").textContent = String(data.count ?? items.length);

  if (items.length === 0) {
    grid.innerHTML = "";
    empty.style.display = "";
    return;
  }
  empty.style.display = "none";

  grid.innerHTML = items.map((item) => {
    const stars = item.rating ? "★".repeat(item.rating) + "☆".repeat(5 - item.rating) : "";
    const period = new Date(item.year, item.month - 1, 1)
      .toLocaleDateString(undefined, { month: "short", year: "numeric" });
    return `
      <div class="rev-tile">
        <img class="rev-tile-img" src="${escapeHtml(item.imageUrl)}" alt="Review" loading="lazy" data-full="${escapeHtml(item.imageUrl)}" />
        <div class="rev-tile-body">
          <div class="rev-tile-staff">${escapeHtml(item.staffName || "Receptionist")}</div>
          <div class="rev-tile-date">Added ${escapeHtml(revFormatDate(item.uploadedAt))} · ${escapeHtml(period)}</div>
          ${item.reviewerName ? `<div class="rev-tile-reviewer">${escapeHtml(item.reviewerName)}</div>` : ""}
          ${stars ? `<div class="rev-tile-stars">${stars}</div>` : ""}
          ${item.notes ? `<div class="rev-tile-notes">${escapeHtml(item.notes)}</div>` : ""}
          <div class="rev-approve-actions">
            <button type="button" class="btn rev-btn-approve" data-approve-id="${escapeHtml(item.id)}">Approve</button>
            <button type="button" class="btn rev-btn-reject" data-reject-id="${escapeHtml(item.id)}">Reject</button>
          </div>
        </div>
      </div>`;
  }).join("");

  grid.querySelectorAll("[data-full]").forEach((img) =>
    img.addEventListener("click", () => revOpenLightbox(img.dataset.full)));
  grid.querySelectorAll("[data-approve-id]").forEach((btn) =>
    btn.addEventListener("click", () => revDecide(btn.dataset.approveId, "approve")));
  grid.querySelectorAll("[data-reject-id]").forEach((btn) =>
    btn.addEventListener("click", () => revDecide(btn.dataset.rejectId, "reject")));
}

async function revDecide(id, action) {
  if (!id) return;
  let body;
  if (action === "reject") {
    const reason = prompt("Optional reason for rejecting this review:", "");
    if (reason === null) return; // cancelled
    body = JSON.stringify({ reason });
  }
  try {
    const res = await fetch(`${API}/api/review-uploads/${id}/${action}`, {
      method: "POST",
      headers: {
        Authorization: `Bearer ${token}`,
        "Content-Type": "application/json",
      },
      body: body ?? "{}",
    });
    if (!res.ok) {
      const data = await res.json().catch(() => ({}));
      throw new Error(data.message || `${action} failed (${res.status})`);
    }
    await revLoadQueue();
    await revLoadGallery();
    // Approving/rejecting changes the effective Google-review count, so refresh
    // the KPI dashboard to keep the breakdown in sync.
    await loadDashboard();
  } catch (error) {
    revShowBanner(error.message || `${action} failed.`);
  }
}

function revOpenLightbox(url) {
  const box = document.getElementById("lightbox");
  document.getElementById("lightboxImg").src = url;
  box.style.display = "grid";
}
document.getElementById("lightbox").addEventListener("click", (e) => {
  e.currentTarget.style.display = "none";
  document.getElementById("lightboxImg").removeAttribute("src");
});

document.getElementById("uploadBtn").addEventListener("click", revUploadReview);
// Keep the review controls in step with the month / staff being viewed.
monthPicker.addEventListener("change", () => { revLoadGallery(); if (isAdmin) revLoadQueue(); });
staffPicker.addEventListener("change", () => { revLoadGallery(); });
revWireDropzone();

async function revInit() {
  const approvals = document.getElementById("reviewApprovalsSection");
  if (approvals) approvals.style.display = isAdmin ? "" : "none";
  await revLoadGallery();
  if (isAdmin) await revLoadQueue();
}

